"""Editorial manifest from inspected first-party captures, never from grader guesses."""
import json,pathlib,hashlib,datetime,re
R=pathlib.Path(__file__).resolve().parents[1]; S=R/'sources'
ROWS=[]
def add(slug, name, loc, color, surface, headline, intro, about, titles, bodies, cta, photos, illo, closing, logo=None):
 c=json.loads((S/slug/'capture.json').read_text());a=json.loads((S/slug/'assets.json').read_text());a={x['index']:x for x in a if x.get('local')}
 l=a[logo] if logo is not None else next(iter(a.values()))
 assert l['transparent'],slug
 rows=[]
 for i,alt,caption in photos:
  x=a[i]; rows.append(dict(local=str(pathlib.Path(x['local']).relative_to(R)),url=x['url'],alt=alt,caption=caption))
 rec=dict(slug=slug,name=name,website=c['official_url'],eligibility='verified',location=loc,brand_color=color,logo_surface=surface,headline=headline,intro=intro,about=about,tagline=closing,services_heading=titles[0]+' & more',services=[dict(title=t,body=b) for t,b in zip(titles,bodies)],cta_url=cta or c['official_url'],cta_label='Explore the menu' if illo in ('food','chicken','taproom') else 'Visit '+name,contact_copy=('Find current menus, hours, locations and ordering information on the official website.' if illo in ('food','chicken','taproom') else 'Explore the official website for current services, appointments and contact details.'),cta_heading=closing,cta_copy='Connect with '+name+' through the official website.',photos=rows,illustration=illo,logo_local=str(pathlib.Path(l['local']).relative_to(R)),logo_url=l['url'],logo_source_page=c['official_url'],logo_dimensions=[l['width'],l['height']],logo_sha256=l['sha256'],logo_format=l['format'],logo_bytes=l['bytes'],verified_at=l['fetched_at'],source_urls=[c['official_url']]+(['https://www.redhilldentaloffice.com/about-us/office-tour/'] if slug=='red-hill-dental-office' else []),dedupe_evidence=dict(inventory='prior-build-inventory.json',registry_scan=c['dedupe_evidence'],source_checked_at=datetime.datetime.now(datetime.timezone.utc).isoformat()))
 ROWS.append(rec)

