def norm(s):return re.sub(r'[^a-z0-9]','',re.sub(r'^(the )|\b(inc|llc|ltd|co|corporation)\b','',s.lower()).replace('&','and'))
prior=json.loads((S/'prior-build-inventory.json').read_text())['rows'];seen={norm(x['name']) for x in prior}
assert all(norm(x['name']) not in seen for x in ROWS),'Prior business selected'
from urllib.parse import urlparse
host=lambda u:(urlparse(u).hostname or '').lower().removeprefix('www.')
domains={host(x.get('official','')) for x in prior if x.get('official')}
assert all(host(x['website']) not in domains for x in ROWS),'Prior official domain selected'
assert len(ROWS)==20
(S/'manifest-first10.json').write_text(json.dumps(dict(records=ROWS[:10]),indent=2,ensure_ascii=False))
(S/'manifest.json').write_text(json.dumps(dict(records=ROWS),indent=2,ensure_ascii=False))
print('Source-complete proof records:',len(ROWS))
